INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 5, 'theory', 'Quiz: hash tables');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 0, 'A table has 16 slots, and the slot number is the key divided by 16, remainder. What happens if all keys are multiples of 16?', '["The keys spread evenly across the slots", "All keys land in slot 0 — the table degenerates into one long chain", "The table grows to 32 slots by itself", "Nothing changes: a division remainder is always random"]', 1, 'The division method is sensitive to patterns in the keys: keys that are multiples of the size all fall into one slot. That is why a prime size or the multiplication method, which mixes the bits, is used.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 1, 'Why can’t a deleted key simply be erased from its slot in open addressing?', '["The freed spot cannot be reused", "It would break the order of keys in the table", "The run would break: a search for keys further along the probe path would conclude they are not there", "Erasing requires rehashing the whole table"]', 2, 'A search stops at the first empty slot. A tombstone says: “someone was here, keep going”, while an insertion may still take its place.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 2, 'What guarantees the correctness of a hash table with respect to keys?', '["If keys are equal, their hashes must be equal", "If hashes are equal, the keys must be equal", "The hash of every key must be unique", "The hash of a key must change on every access"]', 0, 'Different keys may have equal hashes (a collision), but equal keys with different hashes get lost in the table — which is also why mutable keys are dangerous.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 3, 'The table has doubled in size. Why can’t the keys just be copied to the same slot numbers in the new table?', '["The new table uses different hash functions", "The slot number is a remainder by the size, so with a new size a key gets a new number: it must be inserted again", "The old slots cannot be freed", "Copying would violate the load factor"]', 1, 'The hash of the key is the same, but the slot number is computed from the table size. Rehashing is expensive but rare, so the amortized cost of an insertion is constant.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 4, 'For which task is a hash table not suitable?', '["Counting word frequencies in a text", "Checking “has this number been seen before”", "Finding the key closest in value to a given one", "Grouping words by anagram"]', 2, 'A hash does not keep order and cannot find neighbors by value or ranges — for that you need ordered structures, such as search trees.');
